function posed(p){
 const clip=CLIPS[p.clip];
 let q=SimKit.pose.sample(clip,Math.min(p.phase,clip[clip.length-1][0]));
 if(p.phase>clip[clip.length-1][0]){
  const rest=CLIPS[p.side==='near'?'nearReady':'farReady'][0][1];
  q=SimKit.pose.lerp(q,rest,clamp((p.phase-clip[clip.length-1][0])/.22,0,1));
 }
 return SimKit.pose.placeAt(q,[p.x,p.y]);
}
function stroke(p,name){p.clip=name;p.phase=0;}
function move(p,dt){
 const dx=p.tx-p.x,dy=p.ty-p.y,d=Math.hypot(dx,dy),v=Math.min(d,p.speed*dt);
 if(d>0){p.x+=dx/d*v;p.y+=dy/d*v;}
 p.phase+=dt;
}
// Each shot consists of two free-flight arcs joined by a table impact.
// Coordinates include the fixed camera's foreshortening; downward gravity
// and the contact impulse are solved in projected screen space.
function launch(s,side,start,end,T,bounceFrac){
 const tb=T*bounceFrac;
 const by=side==='near'?296:378;
 const bx=mix(start[0],end[0],bounceFrac);
 s.ball={x:start[0],y:start[1],age:0,start:start.slice(),end:end.slice(),T,tb,
  bounce:[bx,by],side,bounced:false,active:true};
 s.events.push({type:'hit',by:side+'_player'});
}
function arc(a,b,t,T){
 const u=clamp(t/T,0,1);return [mix(a[0],b[0],u),mix(a[1],b[1],u)-460*t*(T-t)];
}
function nearHit(s,plan){
 const p=s.near;
 const hand=posed(p).right_wrist;
 const start=[hand[0]+7,hand[1]-8];
 s.plan=plan;
 s.far.tx=plan.farX;s.far.ty=plan.farY||294;
 s.farPrepared=false;
 launch(s,'near',start,[plan.farX+(plan.offset||-52),plan.hitY||209],plan.flight||.6,plan.bounceFrac||.38);
}
function farHit(s){
 const p=s.plan;
 const start=[s.ball.end[0],s.ball.end[1]];
 const nx=p.returnX||s.near.tx+38;
 const ny=p.returnY||411;
 launch(s,'far',start,[nx,ny],p.reply||.52,.64);
 s.farPrepared=true;
}
